<?php

declare(strict_types=1);

namespace OpenTelemetry\Contrib\Ci;

/**
 * One generated workflow per project, so each has its own status, badge
 * and run history. See README.md in .github/ci.
 */
final class Workflows
{
    public const PATTERN = '.github/workflows/project-*.yml';

    // Changing any of these can change every project's cells or jobs.
    private const SHARED_PATHS = [
        '.github/workflows/php-project.yml',
        '.github/ci/matrix.php',
        '.github/ci/composer.json',
        '.github/ci/src/**',
    ];

    private const REGENERATE = 'Run make ci-generate.';

    public static function path(Project $project): string
    {
        return str_replace('*', strtr(strtolower($project->name), '/', '-'), self::PATTERN);
    }

    /**
     * @param list<Project> $projects the projects CI runs
     * @return array<string, string> each workflow's contents, by path, sorted
     */
    public static function generate(array $projects): array
    {
        $workflows = [];
        foreach ($projects as $project) {
            $workflows[self::path($project)] = self::workflow($project);
        }
        ksort($workflows);

        return $workflows;
    }

    /**
     * What differs between the workflows on disk and the ones generate()
     * writes, as GitHub annotations.
     *
     * @param list<Project> $projects the projects CI runs
     * @param array<string, string> $workflows the workflows on disk, by path
     * @return list<string>
     */
    public static function problems(array $projects, array $workflows): array
    {
        $problems = [];
        $owners = [];
        foreach ($projects as $project) {
            $path = self::path($project);
            if (isset($owners[$path])) {
                $problems[] = self::error($project->file(), sprintf('src/%s and src/%s would share the workflow %s. Rename one.', $project->name, $owners[$path], $path));
            }
            $owners[$path] = $project->name;
        }
        if ($problems) {
            return $problems;
        }

        foreach (self::generate($projects) as $path => $expected) {
            if (!isset($workflows[$path])) {
                $problems[] = self::error($path, sprintf('src/%s has no workflow. %s', $owners[$path], self::REGENERATE));
            } elseif ($workflows[$path] !== $expected) {
                $problems[] = self::error($path, "$path differs from what matrix.php generates. " . self::REGENERATE);
            }
        }
        foreach (array_diff_key($workflows, $owners) as $path => $contents) {
            $problems[] = self::error($path, "$path has no project. " . self::REGENERATE);
        }

        return $problems;
    }

    private static function workflow(Project $project): string
    {
        $triggers = ["src/$project->name/**", self::path($project), ...self::SHARED_PATHS];
        if ($services = $project->ci->services ?? []) {
            $triggers[] = 'docker-compose.yaml';
            foreach ($services as $service) {
                $triggers[] = "docker/$service/**";
            }
        }
        $paths = '';
        foreach ($triggers as $path) {
            $paths .= "      - '$path'\n";
        }

        return <<<YAML
            # Generated by .github/ci/matrix.php --generate. Do not edit.
            # See .github/ci/README.md.
            name: $project->name

            on:
              push:
                branches: [ main ]
                paths:
            $paths  pull_request:
                branches: [ main ]
                paths:
            $paths  schedule:
                - cron: '17 4 * * 1' # weekly, against new dependency releases
              workflow_dispatch:

            permissions:
              contents: read

            # Only pull requests cancel. A newer push to main may not touch this
            # project, and then nothing would test the cancelled commit.
            concurrency:
              group: \${{ github.workflow }}-\${{ github.event.pull_request.number || github.run_id }}
              cancel-in-progress: true

            jobs:
              php:
                name: CI
                uses: ./.github/workflows/php-project.yml # zizmor: ignore[self-repository] actionlint doesn't support \$/ yet
                with:
                  project: $project->name
                secrets:
                  CODECOV_TOKEN: \${{ secrets.CODECOV_TOKEN }}

            YAML;
    }

    private static function error(string $file, string $message): string
    {
        return "::error file=$file::$message";
    }
}
